/*
 * Controller for the opt-in faust2max6 runtime test.
 *
 * The surrounding patch is generated by test_max_runtime.py with py2max.
 * This script starts DSP, plays one MIDI note, measures the signal, changes
 * the external to 24 voices, plays a second note, and measures again.  It
 * writes the result before asking thispatcher to close the test patch.
 */

inlets = 1;
outlets = 4;

var resultPath = jsarguments[1];
var stepTask = null;
var watchdogTask = null;
var measurement = 0;
var baseline = 0.0;
var finished = false;

function loadbang()
{
    stepTask = new Task(startDSP, this);
    watchdogTask = new Task(timeout, this);
    stepTask.schedule(500);
    watchdogTask.schedule(15000);
}

function startDSP()
{
    outlet(2, 1);
    stepTask = new Task(playFirstNote, this);
    stepTask.schedule(800);
}

function playFirstNote()
{
    outlet(0, "midievent", 144, 60, 127);
    stepTask = new Task(measureFirstNote, this);
    stepTask.schedule(600);
}

function measureFirstNote()
{
    measurement = 1;
    outlet(1, "bang");
}

function reconfigurePolyphony()
{
    outlet(0, "midievent", 128, 60, 0);
    outlet(0, "polyphony", 24);
    stepTask = new Task(playSecondNote, this);
    stepTask.schedule(1000);
}

function playSecondNote()
{
    outlet(0, "midievent", 144, 64, 127);
    stepTask = new Task(measureSecondNote, this);
    stepTask.schedule(600);
}

function measureSecondNote()
{
    measurement = 2;
    outlet(1, "bang");
}

function msg_float(value)
{
    var level = Math.abs(value);
    if (measurement === 1) {
        measurement = 0;
        baseline = level;
        reconfigurePolyphony();
    } else if (measurement === 2) {
        measurement = 0;
        finish(level);
    }
}

function finish(afterPolyphony)
{
    var passed = baseline > 0.01 && afterPolyphony > 0.01;
    writeResult(passed, baseline, afterPolyphony, "");
    outlet(0, "midievent", 128, 64, 0);
    closePatch();
}

function timeout()
{
    writeResult(false, baseline, 0.0, "Max runtime test timed out");
    closePatch();
}

function writeResult(passed, before, after, error)
{
    if (finished) {
        return;
    }
    finished = true;
    if (watchdogTask !== null) {
        watchdogTask.cancel();
    }

    var file = new File(resultPath, "write", "TEXT");
    if (!file.isopen) {
        post("faust2max6 runtime test cannot open " + resultPath + "\n");
        return;
    }
    file.eof = 0;
    file.writestring(
        "{\"passed\":" + (passed ? "true" : "false") +
        ",\"before\":" + before +
        ",\"after_polyphony\":" + after +
        ",\"polyphony\":24" +
        ",\"error\":\"" + error + "\"}"
    );
    file.close();
}

function closePatch()
{
    outlet(2, 0);
    outlet(3, "dispose");
}
